  const payCur = sum(inW(DEMO.hr, R.current[0], R.current[1]), "payroll"), revCur = sum(inW(BASE, R.current[0], R.current[1]), "revenue");
  const downRows = inW(BASE, 15, 15).filter(ricoh).filter(r => r.shift === "Ночь");
