    r3Down: fHours(sum(inW(BASE, ca, cb).filter(r3), "downtime")), r3Before: fPct(rate(inW(BASE, ba, bb).filter(r3))), r3Now: fPct(rate(inW(BASE, ca, cb).filter(r3))),
