/* ---------- Графики ---------- */

let chartQueue = [], chartUid = 0;
const MONTHS = ["янв", "фев", "мар", "апр", "май", "июн", "июл", "авг", "сен", "окт", "ноя", "дек"];
const weekShort = w => { const d = weekStart(w); return d.getUTCDate() + " " + MONTHS[d.getUTCMonth()]; };
const niceStep = max => [0.001, 0.002, 0.005, 0.01, 0.02, 0.05, 0.1, 0.2, 0.5].find(s => max / s <= 4) || 1;
