  attack: { sources: [], used: "нет, инструменты не вызывались", result: "Инструкция заблокирована", kind: "block", refuse: true },
  unknown: { sources: [], used: "нет подходящей витрины", result: "«Не знаю»", kind: "ok", unknown: true },
