  const taskRows = (k, it) => it.tasks.map((tk, i) => { const p = `out.${k}.tasks.${i}`, base = `oc-${k}-${i}`, er = E[`${k}.${i}`]; return `<div class="oc-task">
      <div class="field"><label for="${base}-t">Задача</label><input id="${base}-t" data-bind="${p}.title" value="${esc(tk.title)}" placeholder="${it.kind === "dev" ? "Если пусто, задачей станет само решение" : "Что сделать"}"></div>
      <div class="sched wide"><div class="field"><label for="${base}-o">Исполнитель</label>${peoplePick(base + "-o", p + ".owner", tk.owner)}</div><div class="field"><label for="${base}-d">Срок</label>${datePick(base + "-d", p + ".due", tk.due)}</div></div>
      <div class="field"><label for="${base}-c">Готово, когда</label><input id="${base}-c" data-bind="${p}.criteria" value="${esc(tk.criteria)}"></div>
      ${er ? `<p class="err">${esc(er)}</p>` : ""}${it.tasks.length > (it.kind === "dev" ? 1 : 0) ? `<button type="button" class="btn btn-quiet btn-sm" data-act="ocTaskDel" data-arg="${k}:${i}">Убрать задачу</button>` : ""}</div>`; }).join("");
