function setDecision(d, id, specs) {
  const dev = id || DEMO.deviationsMeta.main, C = caseOf(dev);
  d.dev = dev;
  d.tasks = (specs || [{ title: d.text, owner: d.owner, due: d.due, criteria: "" }]).map(s => mkTask({ dev, why: d.text, ...s, log: [{ at: S.today, who: "Руководитель", text: d.meetDay ? `Задача назначена на встрече ${d.meetDay}` : "Задача назначена" }] }));
  syncDec(d); C.decision = d; C.status = "work"; C.deciding = false;
  d.tasks.forEach(t => notify("manager", `Новая задача: ${t.title}, до ${dueShort(t.due)}`, "#/tasks/" + t.id, t.owner));
}
const notify = (role, text, href, to) => S.notices.push({ role, text, href, to, read: false });
